class GraphModel:
    """Replays the model as a CUDA graph per input shape (removes per-layer Python/launch overhead).
    Full-ish batches are padded to `batch`; small batches, too many shapes, or a failed capture fall
    back to eager. Same kernels, same outputs."""
    MAX_SHAPES = 16

    def __init__(self, model, batch):
        self.m, self.b, self.graphs, self.pool = model, batch, {}, None

    def eager(self, x):
        y = self.m(x)
        return y[0] if isinstance(y, (list, tuple)) else y

    def capture(self, shape, like):
        import torch
        xs = torch.zeros((self.b, *shape), device=like.device, dtype=like.dtype)
        s = torch.cuda.Stream()
        s.wait_stream(torch.cuda.current_stream())
        with torch.cuda.stream(s):
            for _ in range(3):
                self.eager(xs)
        torch.cuda.current_stream().wait_stream(s)
        g = torch.cuda.CUDAGraph()
        with torch.cuda.graph(g, pool=self.pool):
            ys = self.eager(xs)
        self.pool = g.pool()
        return g, xs, ys

    def __call__(self, x):
        n, shape = len(x), tuple(x.shape[1:])
        if n < self.b // 2 or n > self.b:
            return self.eager(x)
        if shape not in self.graphs:
            try:
                self.graphs[shape] = self.capture(shape, x) if len(self.graphs) < self.MAX_SHAPES else None
            except Exception:
                self.graphs[shape] = None
        e = self.graphs[shape]
        if e is None:
            return self.eager(x)
        g, xs, ys = e
        xs[:n].copy_(x)
        g.replay()
        return ys[:n]  # read before the next replay (infer() syncs via .cpu() in postprocess)


def load_model(path, batch=64):
    import torch
    from ultralytics.nn.autobackend import AutoBackend
    m = AutoBackend(path, device=torch.device("cuda"), fp16=True, fuse=True)
    m.eval()
    return GraphModel(m, batch)

